mapper.select:
/* DgnssMapper.selectAllStdtList */
SELECT gm.stdt_id
FROM group_info gi
	INNER JOIN group_member gm
		ON gi.group_id = gm.group_id
WHERE gi.cla_id = #{claId}

/* DgnssMapper.selectDgnssStdtList */
SELECT tdri.stdt_id
FROM tb_dgnss_info tdi
INNER JOIN tb_dgnss_result_info tdri ON tdi.id = tdri.dgnss_id
WHERE tdi.cla_id = #{claId}
GROUP BY tdri.stdt_id

mapper.delete:
/* etcMapper.deleteTargetStListResultInfo */
DELETE FROM tb_dgnss_result_info
WHERE stdt_id in (

	#{item}
)

/* etcMapper.deleteTargetStListAnswer */
DELETE FROM tb_dgnss_answer
WHERE MEM_ID in (

	#{item}
)

mapper.select:
/* DgnssMapper.selectTcDgnssInfo */ SELECT a1.id AS dgnssId , a1.ord_no AS ordNo , a1.cla_id AS claId , a1.dgnss_at AS dgnssAt , a1.paper_idx AS paperIdx , DATE_FORMAT(a1.dgnss_st_dt, '%Y. %m. %d.') AS dgnssStDt , DATE_FORMAT(a1.dgnss_ed_dt, '%Y. %m. %d.') AS dgnssEdDt , COUNT( DISTINCT CASE WHEN b1.subm_at = 'Y' THEN b1.stdt_id END ) AS stSubmCnt , ( SELECT COUNT(DISTINCT gm2.stdt_id) FROM group_info gi2 INNER JOIN group_member gm2 ON gi2.group_id = gm2.group_id WHERE gi2.cla_id = a1.cla_id
) AS stTotalCnt , ( SELECT COUNT(DISTINCT gm2.stdt_id) FROM group_info gi2 INNER JOIN group_member gm2 ON gi2.group_id = gm2.group_id WHERE gi2.cla_id = a1.cla_id
AND NOT EXISTS ( SELECT 1 FROM tb_dgnss_result_info b2 WHERE b2.stdt_id = gm2.stdt_id AND b2.dgnss_id = a1.id ) ) AS notDgnssStartCnt , ( SELECT GROUP_CONCAT(DISTINCT gm2.stdt_id) FROM group_info gi2 INNER JOIN group_member gm2 ON gi2.group_id = gm2.group_id WHERE gi2.cla_id = a1.cla_id
AND NOT EXISTS ( SELECT 1 FROM tb_dgnss_result_info b2 WHERE b2.stdt_id = gm2.stdt_id AND b2.dgnss_id = a1.id ) ) AS notDgnssStartList , a1.tc_id AS tcId FROM tb_dgnss_info a1 INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN group_info gi ON a1.cla_id = gi.cla_id INNER JOIN group_member gm ON gi.group_id = gm.group_id AND b1.stdt_id = gm.stdt_id
WHERE a1.cla_id = #{claId} GROUP BY a1.id

/* DgnssMapper.selectActvStdtCnt */
SELECT COUNT(*)
FROM group_info gi
	INNER JOIN group_member gm
		ON gi.group_id = gm.group_id
WHERE gi.cla_id = #{claId}

mapper.insert:
		/* DgnssMapper.insertDgnssInfo */
		INSERT INTO tb_dgnss_info
        (
            cla_id, 
            tc_id, 
            ord_no

                , paper_idx

        )
        VALUES
        (
            #{claId}, 
            #{tcId}, 
            #{ordNo}

                , #{paperIdx}

        )

mapper.select:
/* DgnssMapper.selectExistsDgnssInfo */
SELECT COUNT(*)
FROM tb_dgnss_info
WHERE cla_id = #{claId}
  AND tc_id = #{tcId}
  AND ord_no = #{ordNo}
  AND paper_idx = #{paperIdx}

/* DgnssMapper.selectTcId */
SELECT u.tc_id
FROM group_info gi
	INNER JOIN `user` u
		ON gi.host_user_no = u.user_no
WHERE gi.cla_id = #{claId}

mapper.insert:
		/* DgnssMapper.insertDgnssResult */
		INSERT INTO tb_dgnss_omr
        (
            MEM_ID, 
            CLASS_NO

                , PAPER_IDX

        )
        VALUES
        (
	        #{stdtId}, 
	        #{claId}

	            , '5'

        )

		/* DgnssMapper.insertDgnssResult */
		INSERT INTO tb_dgnss_result_info
        (
            dgnss_id, 
            stdt_id, 
            omr_id
        )
        VALUES
        (
            #{dgnssId}, 
            #{stdtId}, 
            #{omrIdx}
        )

/* DgnssMapper.insertDgnssAnswer */ INSERT INTO tb_dgnss_answer ( MEM_ID, DGNSS_RESULT_ID, DGNSS_ORD, SCH_GRADE, TEST_IDX
, DGNSS_ID , PAPER_IDX
) VALUES ( #{stdtId}, #{dgnssResultId}, #{ordNo}, #{schGrade}, #{dgnssId}
, 'DGNSS_10' , '5'
)

mapper.select:
/* DgnssMapper.selectTcDgnssInfoOne */ SELECT a1.id AS dgnssId , a1.ord_no AS ordNo , a1.cla_id AS claId , a1.dgnss_at AS dgnssAt , DATE_FORMAT(dgnss_st_dt, '%Y-%m-%d %H:%i:%s') AS dgnssStDt , DATE_FORMAT(dgnss_ed_dt, '%Y-%m-%d %H:%i:%s') AS dgnssEdDt , COUNT(DISTINCT CASE WHEN b1.subm_at = 'Y' THEN b1.stdt_id END) AS stSubmCnt FROM tb_dgnss_info a1 INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN group_info gi ON a1.cla_id = gi.cla_id INNER JOIN group_member gm ON gi.group_id = gm.group_id AND b1.stdt_id = gm.stdt_id
WHERE a1.cla_id = #{claId}
AND a1.paper_idx = '1'
AND a1.paper_idx = '2'
AND a1.ord_no = #{ordNo} GROUP BY a1.id ORDER BY a1.id DESC LIMIT 1

mapper.update:
/* DgnssMapper.updateDgnssInfo */
UPDATE tb_dgnss_info
SET    dgnss_at = 'N',
       dgnss_ed_dt = NOW()
WHERE  id = #{dgnssId}

mapper.select:
/* DgnssMapper.selectSubmitYnByDgnssResultId */
SELECT subm_at
FROM tb_dgnss_result_info
WHERE id = #{dgnssResultId}
LIMIT 1

/* DgnssMapper.selectStdtIdFromDgnssResultId */
SELECT stdt_id
FROM tb_dgnss_result_info
WHERE id = #{dgnssResultId}

