 FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 34, OMR.34) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 35, OMR.35) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 36, OMR.36) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 37, OMR.37) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 38, OMR.38) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 39, OMR.39) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 40, OMR.40) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 41, OMR.41) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 42, OMR.42) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 43, OMR.43) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 44, OMR.44) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 45, OMR.45) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 46, OMR.46) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 47, OMR.47) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 48, OMR.48) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 49, OMR.49) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 50, OMR.50) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 51, OMR.51) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 52, OMR.52) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 53, OMR.53) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 54, OMR.54) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 55, OMR.55) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 56, OMR.56) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 57, OMR.57) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 58, OMR.58) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 59, OMR.59) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 60, OMR.60) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 61, OMR.61) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 62, OMR.62) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 63, OMR.63) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 64, OMR.64) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 65, OMR.65) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 66, OMR.66) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 67, OMR.67) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 68, OMR.68) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 69, OMR.69) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 70, OMR.70) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 71, OMR.71) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 72, OMR.72) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 73, OMR.73) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 74, OMR.74) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 75, OMR.75) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 76, OMR.76) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 77, OMR.77) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 78, OMR.78) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 79, OMR.79) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 80, OMR.80) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 81, OMR.81) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 82, OMR.82) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 83, OMR.83) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 84, OMR.84) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 85, OMR.85) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 86, OMR.86) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 87, OMR.87) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 88, OMR.88) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 89, OMR.89) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 90, OMR.90) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 91, OMR.91) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 92, OMR.92) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 93, OMR.93) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 94, OMR.94) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 95, OMR.95) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 96, OMR.96) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 97, OMR.97) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 98, OMR.98) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 99, OMR.99) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 100, OMR.100) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 101, OMR.101) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 102, OMR.102) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 103, OMR.103) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 104, OMR.104) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 105, OMR.105) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 106, OMR.106) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 107, OMR.107) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 108, OMR.108) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 109, OMR.109) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 110, OMR.110) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 111, OMR.111) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 112, OMR.112) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 113, OMR.113) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 114, OMR.114) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 115, OMR.115) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 116, OMR.116) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 117, OMR.117) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 118, OMR.118) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 119, OMR.119) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 120, OMR.120) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 121, OMR.121) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 122, OMR.122) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 123, OMR.123) , ', ', FN_GET_SCORE_BY_ANSWER(OMR.PAPER_IDX, 124, OMR.124) ,']') AS ANSWERS FROM tb_dgnss_result_info a1 INNER JOIN tb_dgnss_omr OMR ON a1.omr_id = OMR.OMR_IDX WHERE a1.id = #{dgnssResultId} )
, REPEATED_RESPONSE_YN = 'Y'
WHERE aa.DGNSS_RESULT_ID = #{dgnssResultId}

mapper.select:
/* DgnssMapper.selectAnswerIdx */
SELECT ANSWER_IDX
FROM tb_dgnss_answer
WHERE DGNSS_RESULT_ID = #{dgnssResultId}

/* DgnssMapper.getDgnssReportSection */
SELECT A1.MEM_ID, A1.num AS CLASS_NO, IFNULL(B.T_SCORE_01_01, -1) AS T_SCORE_01_01, IFNULL(B.T_SCORE_01_02, -1) AS T_SCORE_01_02, IFNULL(B.T_SCORE_02_01, -1) AS T_SCORE_02_01, IFNULL(B.T_SCORE_02_02, -1) AS T_SCORE_02_02, IFNULL(B.T_SCORE_02_03, -1) AS T_SCORE_02_03, IFNULL(B.T_SCORE_03_01, -1) AS T_SCORE_03_01, IFNULL(B.T_SCORE_03_02, -1) AS T_SCORE_03_02, IFNULL(B.T_SCORE_03_03, -1) AS T_SCORE_03_03, IFNULL(B.T_SCORE_04_01, -1) AS T_SCORE_04_01, IFNULL(B.T_SCORE_04_02, -1) AS T_SCORE_04_02, IFNULL(B.T_SCORE_05_01, -1) AS T_SCORE_05_01, IFNULL(C.T_SCORE_01_01_01, -1) AS T_SCORE_01_01_01, IFNULL(C.T_SCORE_01_01_02, -1) AS T_SCORE_01_01_02, IFNULL(C.T_SCORE_01_01_03, -1) AS T_SCORE_01_01_03, IFNULL(C.T_SCORE_01_02_01, -1) AS T_SCORE_01_02_01, IFNULL(C.T_SCORE_01_02_02, -1) AS T_SCORE_01_02_02, IFNULL(C.T_SCORE_01_02_03, -1) AS T_SCORE_01_02_03, IFNULL(C.T_SCORE_01_02_04, -1) AS T_SCORE_01_02_04, IFNULL(C.T_SCORE_02_01_01, -1) AS T_SCORE_02_01_01, IFNULL(C.T_SCORE_02_01_02, -1) AS T_SCORE_02_01_02, IFNULL(C.T_SCORE_02_01_03, -1) AS T_SCORE_02_01_03, IFNULL(C.T_SCORE_02_02_01, -1) AS T_SCORE_02_02_01, IFNULL(C.T_SCORE_02_02_02, -1) AS T_SCORE_02_02_02, IFNULL(C.T_SCORE_02_02_03, -1) AS T_SCORE_02_02_03, IFNULL(C.T_SCORE_02_02_04, -1) AS T_SCORE_02_02_04, IFNULL(C.T_SCORE_02_02_05, -1) AS T_SCORE_02_02_05, IFNULL(C.T_SCORE_02_03_01, -1) AS T_SCORE_02_03_01, IFNULL(C.T_SCORE_02_03_02, -1) AS T_SCORE_02_03_02, IFNULL(C.T_SCORE_02_03_03, -1) AS T_SCORE_02_03_03, IFNULL(C.T_SCORE_02_03_04, -1) AS T_SCORE_02_03_04, IFNULL(C.T_SCORE_03_01_01, -1) AS T_SCORE_03_01_01, IFNULL(C.T_SCORE_03_01_02, -1) AS T_SCORE_03_01_02, IFNULL(C.T_SCORE_03_01_03, -1) AS T_SCORE_03_01_03, IFNULL(C.T_SCORE_03_02_01, -1) AS T_SCORE_03_02_01, IFNULL(C.T_SCORE_03_02_02, -1) AS T_SCORE_03_02_02, IFNULL(C.T_SCORE_03_02_03, -1) AS T_SCORE_03_02_03, IFNULL(C.T_SCORE_03_02_04, -1) AS T_SCORE_03_02_04, IFNULL(C.T_SCORE_03_02_05, -1) AS T_SCORE_03_02_05, IFNULL(C.T_SCORE_03_03_01, -1) AS T_SCORE_03_03_01, IFNULL(C.T_SCORE_03_03_02, -1) AS T_SCORE_03_03_02, IFNULL(C.T_SCORE_04_01_01, -1) AS T_SCORE_04_01_01, IFNULL(C.T_SCORE_04_01_02, -1) AS T_SCORE_04_01_02, IFNULL(C.T_SCORE_04_01_03, -1) AS T_SCORE_04_01_03, IFNULL(C.T_SCORE_04_02_01, -1) AS T_SCORE_04_02_01, IFNULL(C.T_SCORE_04_02_02, -1) AS T_SCORE_04_02_02, IFNULL(C.T_SCORE_04_02_03, -1) AS T_SCORE_04_02_03, IFNULL(C.T_SCORE_05_01_01, -1) AS T_SCORE_05_01_01, IFNULL(C.T_SCORE_05_01_02, -1) AS T_SCORE_05_01_02, IFNULL(C.T_SCORE_05_01_03, -1) AS T_SCORE_05_01_03 FROM ( SELECT a1_1.id, gm.member_no AS num, a1_1.stdt_id AS MEM_ID FROM tb_dgnss_result_info a1_1 INNER JOIN tb_dgnss_info tdi ON a1_1.dgnss_id = tdi.id INNER JOIN group_info gi ON tdi.cla_id = gi.cla_id INNER JOIN group_member gm ON gi.group_id = gm.group_id AND a1_1.stdt_id = gm.stdt_id
WHERE a1_1.dgnss_id = #{TEST_IDX} AND EXISTS ( SELECT 1 FROM tb_dgnss_answer_report tdar WHERE tdar.ANSWER_IDX = a1_1.id ) ) A1 LEFT JOIN ( SELECT DA.MEM_ID, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_03, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_01, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_02, MAX( CASE WHEN DS.CLASS3 = '05' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_05_01 FROM TB_DGNSS_ANSWER_REPORT DAR INNER JOIN TB_DGNSS_ANSWER DA ON DAR.ANSWER_IDX = DA.ANSWER_IDX INNER JOIN TB_DGNSS_SECTION DS ON DAR.SECTION_ID = DS.SECTION_ID WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = 4 GROUP BY DA.MEM_ID ) B ON A1.MEM_ID = B.MEM_ID LEFT JOIN ( SELECT DA.MEM_ID, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_02, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_03, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_02, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_03, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '04' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_04, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_03, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_03, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '04' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_04, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '05' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_05, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '03' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_03_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '03' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_03_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '03' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_03_03, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '03' AND DS.CLASS5 = '04' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_03_04, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '04' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_04, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '05' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_05, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '03' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_03_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '03' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_03_02, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_01_01, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_01_02, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_01_03, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_02_01, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_02_02, MAX( CASE WHEN DS.CLASS3 = '04' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_04_02_03, MAX( CASE WHEN DS.CLASS3 = '05' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_05_01_01, MAX( CASE WHEN DS.CLASS3 = '05' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_05_01_02, MAX( CASE WHEN DS.CLASS3 = '05' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_05_01_03 FROM TB_DGNSS_ANSWER_REPORT DAR INNER JOIN TB_DGNSS_ANSWER DA ON DAR.ANSWER_IDX = DA.ANSWER_IDX INNER JOIN TB_DGNSS_SECTION DS ON DAR.SECTION_ID = DS.SECTION_ID WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = 5 GROUP BY DA.MEM_ID ) C ON B.MEM_ID = C.MEM_ID ORDER BY A1.num;
SELECT A1.MEM_ID, A1.num AS CLASS_NO, IFNULL(A.T_SCORE_01, -1) AS T_SCORE_01, IFNULL(A.T_SCORE_02, -1) AS T_SCORE_02, IFNULL(A.T_SCORE_03, -1) AS T_SCORE_03, IFNULL(B.T_SCORE_01_01, -1) AS T_SCORE_01_01, IFNULL(B.T_SCORE_01_02, -1) AS T_SCORE_01_02, IFNULL(B.T_SCORE_02_01, -1) AS T_SCORE_02_01, IFNULL(B.T_SCORE_02_02, -1) AS T_SCORE_02_02, IFNULL(B.T_SCORE_03_01, -1) AS T_SCORE_03_01, IFNULL(B.T_SCORE_03_02, -1) AS T_SCORE_03_02, IFNULL(C.T_SCORE_01_01_01, -1) AS T_SCORE_01_01_01, IFNULL(C.T_SCORE_01_01_02, -1) AS T_SCORE_01_01_02, IFNULL(C.T_SCORE_01_01_03, -1) AS T_SCORE_01_01_03, IFNULL(C.T_SCORE_01_02_01, -1) AS T_SCORE_01_02_01, IFNULL(C.T_SCORE_01_02_02, -1) AS T_SCORE_01_02_02, IFNULL(C.T_SCORE_01_02_03, -1) AS T_SCORE_01_02_03, IFNULL(C.T_SCORE_02_01_01, -1) AS T_SCORE_02_01_01, IFNULL(C.T_SCORE_02_01_02, -1) AS T_SCORE_02_01_02, IFNULL(C.T_SCORE_02_01_03, -1) AS T_SCORE_02_01_03, IFNULL(C.T_SCORE_02_02_01, -1) AS T_SCORE_02_02_01, IFNULL(C.T_SCORE_02_02_02, -1) AS T_SCORE_02_02_02, IFNULL(C.T_SCORE_02_02_03, -1) AS T_SCORE_02_02_03, IFNULL(C.T_SCORE_03_01_01, -1) AS T_SCORE_03_01_01, IFNULL(C.T_SCORE_03_01_02, -1) AS T_SCORE_03_01_02, IFNULL(C.T_SCORE_03_01_03, -1) AS T_SCORE_03_01_03, IFNULL(C.T_SCORE_03_02_01, -1) AS T_SCORE_03_02_01, IFNULL(C.T_SCORE_03_02_02, -1) AS T_SCORE_03_02_02, IFNULL(C.T_SCORE_03_02_03, -1) AS T_SCORE_03_02_03, IFNULL(C.T_SCORE_03_02_04, -1) AS T_SCORE_03_02_04, IFNULL(C.T_SCORE_03_02_05, -1) AS T_SCORE_03_02_05 FROM ( SELECT a1_1.id, gm.member_no AS num, a1_1.stdt_id AS MEM_ID FROM tb_dgnss_result_info a1_1 INNER JOIN tb_dgnss_info tdi ON a1_1.dgnss_id = tdi.id INNER JOIN group_info gi ON tdi.cla_id = gi.cla_id INNER JOIN group_member gm ON gi.group_id = gm.group_id AND a1_1.stdt_id = gm.stdt_id
WHERE a1_1.dgnss_id = #{TEST_IDX} AND EXISTS ( SELECT 1 FROM tb_dgnss_answer_report tdar WHERE tdar.ANSWER_IDX = a1_1.id ) ) A1 LEFT JOIN ( SELECT DA.MEM_ID, IFNULL(MAX( CASE WHEN DS.CLASS3 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END), NULL) AS T_SCORE_01, IFNULL(MAX( CASE WHEN DS.CLASS3 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END), NULL) AS T_SCORE_02, IFNULL(MAX( CASE WHEN DS.CLASS3 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END), NULL) AS T_SCORE_03 FROM TB_DGNSS_ANSWER DA LEFT JOIN TB_DGNSS_ANSWER_REPORT DAR ON DAR.ANSWER_IDX = DA.ANSWER_IDX LEFT JOIN TB_DGNSS_SECTION DS ON DAR.SECTION_ID = DS.SECTION_ID WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = 3 GROUP BY DA.MEM_ID ) A ON A1.MEM_ID = A.MEM_ID LEFT JOIN ( SELECT DA.MEM_ID, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02 FROM TB_DGNSS_ANSWER_REPORT DAR INNER JOIN TB_DGNSS_ANSWER DA ON DAR.ANSWER_IDX = DA.ANSWER_IDX INNER JOIN TB_DGNSS_SECTION DS ON DAR.SECTION_ID = DS.SECTION_ID WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = 4 GROUP BY DA.MEM_ID ) B ON A.MEM_ID = B.MEM_ID LEFT JOIN ( SELECT DA.MEM_ID, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_02, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_01_03, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_01, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_02, MAX( CASE WHEN DS.CLASS3 = '01' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_01_02_03, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_01_03, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_01, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_02, MAX( CASE WHEN DS.CLASS3 = '02' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_02_02_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '01' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_01_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '01' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_01, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '02' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_02, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '03' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_03, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '04' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_04, MAX( CASE WHEN DS.CLASS3 = '03' AND DS.CLASS4 = '02' AND DS.CLASS5 = '05' THEN IF(ROUND(DAR.T_SCORE, 0) < 0, 0, ROUND(DAR.T_SCORE, 0)) END) AS T_SCORE_03_02_05 FROM TB_DGNSS_ANSWER_REPORT DAR INNER JOIN TB_DGNSS_ANSWER DA ON DAR.ANSWER_IDX = DA.ANSWER_IDX INNER JOIN TB_DGNSS_SECTION DS ON DAR.SECTION_ID = DS.SECTION_ID WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = 5 GROUP BY DA.MEM_ID ) C ON A.MEM_ID = C.MEM_ID ORDER BY A1.num

/* DgnssMapper.getDgnssFirstTest */
SELECT tdi.id
FROM tb_dgnss_info tdi
WHERE tdi.tc_id = (
	SELECT tc_id
	FROM tb_dgnss_info tdi2
	WHERE tdi2.id = #{TEST_IDX}
)
AND tdi.paper_idx = (
	SELECT paper_idx
	FROM tb_dgnss_info tdi2
	WHERE tdi2.id = #{TEST_IDX}
)
AND tdi.cla_id = #{claId}
AND tdi.ord_no = 1

/* DgnssMapper.getDgnssReportStatByTest */ SELECT STAT.SECTION_ID , DS.CLASS3, DS.CLASS4, DS.CLASS5, DS.DEPTH , ROUND(STAT.T_SCORE, 0) AS T_SCORE , IFNULL(ROUND(STAT_FIRST.T_SCORE, 0), 0) AS T_SCORE_FIRST , ROUND(STAT.T_SCORE, 0) - IFNULL(ROUND(STAT_FIRST.T_SCORE, 0), ROUND(STAT.T_SCORE, 0)) AS T_SCORE_GAP FROM ( SELECT DAR.SECTION_ID, IF(ROUND(AVG(DAR.T_SCORE), 2) < 0, 0, ROUND(AVG(DAR.T_SCORE))) AS T_SCORE FROM tb_dgnss_info DT INNER JOIN TB_DGNSS_ANSWER DA ON DT.id = DA.TEST_IDX INNER JOIN TB_DGNSS_ANSWER_REPORT DAR ON DA.ANSWER_IDX = DAR.ANSWER_IDX INNER JOIN tb_dgnss_result_info tdri ON DT.id = tdri.dgnss_id INNER JOIN group_info gi ON DT.cla_id = gi.cla_id INNER JOIN group_member gm ON gi.group_id = gm.group_id AND tdri.stdt_id = gm.stdt_id WHERE DA.TEST_IDX = #{TEST_IDX} AND DAR.DEPTH = #{DEPTH}
AND DA.COCH_DGNSS_QESITM01_MARK <> '주의' AND DA.COCH_DGNSS_QESITM02_MARK <> '주의' AND DA.REPEATED_RESPONSE_YN <> 'Y'
GROUP BY DAR.SECTION_ID) STAT LEFT JOIN (SELECT DAR.SECTION_ID, IF(ROUND(AVG(DAR.T_SCORE), 2) < 0, 0, ROUND(AVG(DAR.T_SCORE))) AS T_SCORE FROM tb_dgnss_info DT INNER JOIN TB_DGNSS_ANSWER DA ON DT.id = DA.TEST_IDX INNER JOIN TB_DGNSS_ANSWER_REPORT DAR ON DA.ANSWER_IDX = DAR.ANSWER_IDX INNER JOIN tb_dgnss_result_info tdri ON DT.id = tdri.dgnss_id INNER JOIN group_info gi ON DT.cla_id = gi.cla_id INNER JOIN group_member gm ON gi.group_id = gm.group_id AND tdri.stdt_id = gm.stdt_id WHERE DA.TEST_IDX = #{FIRST_IDX} AND DAR.DEPTH = #{DEPTH}
AND DA.COCH_DGNSS_QESITM01_MARK <> '주의' AND DA.COCH_DGNSS_QESITM02_MARK <> '주의' AND DA.REPEATED_RESPONSE_YN <> 'Y'
GROUP BY DAR.SECTION_ID) STAT_FIRST ON STAT.SECTION_ID = STAT_FIRST.SECTION_ID INNER JOIN TB_DGNSS_SECTION DS ON STAT.SECTION_ID = DS.SECTION_ID ORDER BY STAT.SECTION_ID

