/* DgnssMapper.selectDgnssAnswerReliabilityFromOtherClasses */ SELECT ROW_NUMBER() OVER(ORDER BY gm.member_no) AS rowNum , b1.stdt_id AS stdtId , gm.nickname AS nickname , gm.member_no AS memberNo , c1.COCH_DGNSS_QESITM02_MARK AS desirable , c1.COCH_DGNSS_QESITM01_MARK AS reaction , c1.REPEATED_RESPONSE_YN AS repeatResponse , lpa.class_id AS lpaClassId , lpa.type_name AS lpaTypeName , lpa.confidence AS lpaConfidence , lpa.status AS lpaStatus , lpa.probabilities_json AS lpaProbabilitiesJson , CASE WHEN c1.LS_ANS01 = 1 THEN '매우 낮음' WHEN c1.LS_ANS01 = 2 THEN '낮음' WHEN c1.LS_ANS01 = 3 THEN '보통' WHEN c1.LS_ANS01 = 4 THEN '높음' WHEN c1.LS_ANS01 = 5 THEN '매우 높음' END styPer , CASE WHEN c1.LS_ANS02 = 1 THEN '매우 낮음' WHEN c1.LS_ANS02 = 2 THEN '낮음' WHEN c1.LS_ANS02 = 3 THEN '보통' WHEN c1.LS_ANS02 = 4 THEN '높음' WHEN c1.LS_ANS02 = 5 THEN '매우 높음' END satisPer , CASE WHEN c1.LS_ANS03 = 1 THEN '친구를 사귀려고' WHEN c1.LS_ANS03 = 2 THEN '미래를 위해서' WHEN c1.LS_ANS03 = 3 THEN '대학 진학' WHEN c1.LS_ANS03 = 4 THEN '주변 기대 때문에' WHEN c1.LS_ANS03 = 5 THEN '모르겠음' END reason , CASE WHEN c1.LS_ANS04 = 1 THEN '거의 안함' WHEN c1.LS_ANS04 = 2 THEN '1시간 미만' WHEN c1.LS_ANS04 = 3 THEN '1~2시간' WHEN c1.LS_ANS04 = 4 THEN '2~3시간' WHEN c1.LS_ANS04 = 5 THEN '3시간 이상' END styTime , CASE WHEN c1.LS_ANS05 = 1 THEN '친구' WHEN c1.LS_ANS05 = 2 THEN '선생님' WHEN c1.LS_ANS05 = 3 THEN '가족' WHEN c1.LS_ANS05 = 4 THEN '상담 전문가' WHEN c1.LS_ANS05 = 5 THEN '기타' END cnsl , CASE WHEN gm.gender = 'M' THEN '남자' WHEN gm.gender = 'F' THEN '여자' ELSE '' END AS gender , c1.ANSWER_IDX AS answerIdx FROM tb_dgnss_info a1 INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN tb_dgnss_answer c1 ON b1.id = c1.DGNSS_RESULT_ID LEFT JOIN tb_dgnss_lpa_result lpa ON c1.ANSWER_IDX = lpa.answer_idx INNER JOIN group_info gi ON gi.cla_id = #{claId} INNER JOIN group_member gm ON gi.group_id = gm.group_id AND b1.stdt_id = gm.stdt_id WHERE a1.cla_id <> #{claId} AND a1.paper_idx = #{paperIdx} AND a1.ord_no = #{ordNo} AND a1.dgnss_at = 'N' AND b1.subm_at = 'Y' AND b1.stdt_id IN
#{stdtId}
ORDER BY gm.member_no

/* DgnssMapper.selectLernType2FromOtherClasses */
SELECT ROW_NUMBER() OVER(ORDER BY gm.member_no) AS rowNum , b1.stdt_id AS stdtId , gm.nickname AS nickname , gm.member_no AS memberNo , c1.COCH_DGNSS_QESITM01_MARK AS reaction , c1.COCH_DGNSS_QESITM02_MARK AS desirable , c1.REPEATED_RESPONSE_YN AS repeatResponse , lpa.class_id AS lpaClassId , lpa.type_name AS lpaTypeName , lpa.confidence AS lpaConfidence , lpa.status AS lpaStatus , lpa.probabilities_json AS lpaProbabilitiesJson , (SELECT IF(ROUND(b1_1.T_SCORE) < 0, 0, ROUND(b1_1.T_SCORE)) FROM tb_dgnss_answer_report b1_1 WHERE b1_1.ANSWER_IDX = c1.ANSWER_IDX AND b1_1.SECTION_ID = '10-22-01-01-0-0') AS '10-22-01-01-0-0' , (SELECT IF(ROUND(b1_2.T_SCORE) < 0, 0, ROUND(b1_2.T_SCORE)) FROM tb_dgnss_answer_report b1_2 WHERE b1_2.ANSWER_IDX = c1.ANSWER_IDX AND b1_2.SECTION_ID = '10-22-01-01-01-0') AS '10-22-01-01-01-0' , (SELECT IF(ROUND(b1_3.T_SCORE) < 0, 0, ROUND(b1_3.T_SCORE)) FROM tb_dgnss_answer_report b1_3 WHERE b1_3.ANSWER_IDX = c1.ANSWER_IDX AND b1_3.SECTION_ID = '10-22-01-01-02-0') AS '10-22-01-01-02-0' , (SELECT IF(ROUND(b1_4.T_SCORE) < 0, 0, ROUND(b1_4.T_SCORE)) FROM tb_dgnss_answer_report b1_4 WHERE b1_4.ANSWER_IDX = c1.ANSWER_IDX AND b1_4.SECTION_ID = '10-22-01-01-03-0') AS '10-22-01-01-03-0' , (SELECT IF(ROUND(b1_5.T_SCORE) < 0, 0, ROUND(b1_5.T_SCORE)) FROM tb_dgnss_answer_report b1_5 WHERE b1_5.ANSWER_IDX = c1.ANSWER_IDX AND b1_5.SECTION_ID = '10-22-01-02-0-0') AS '10-22-01-02-0-0' , (SELECT IF(ROUND(b1_6.T_SCORE) < 0, 0, ROUND(b1_6.T_SCORE)) FROM tb_dgnss_answer_report b1_6 WHERE b1_6.ANSWER_IDX = c1.ANSWER_IDX AND b1_6.SECTION_ID = '10-22-01-02-01-0') AS '10-22-01-02-01-0' , (SELECT IF(ROUND(b1_7.T_SCORE) < 0, 0, ROUND(b1_7.T_SCORE)) FROM tb_dgnss_answer_report b1_7 WHERE b1_7.ANSWER_IDX = c1.ANSWER_IDX AND b1_7.SECTION_ID = '10-22-01-02-02-0') AS '10-22-01-02-02-0' , (SELECT IF(ROUND(b1_8.T_SCORE) < 0, 0, ROUND(b1_8.T_SCORE)) FROM tb_dgnss_answer_report b1_8 WHERE b1_8.ANSWER_IDX = c1.ANSWER_IDX AND b1_8.SECTION_ID = '10-22-01-02-03-0') AS '10-22-01-02-03-0' , (SELECT IF(ROUND(b1_9.T_SCORE) < 0, 0, ROUND(b1_9.T_SCORE)) FROM tb_dgnss_answer_report b1_9 WHERE b1_9.ANSWER_IDX = c1.ANSWER_IDX AND b1_9.SECTION_ID = '10-22-01-02-04-0') AS '10-22-01-02-04-0' , CASE WHEN gm.gender = 'M' THEN '남자' WHEN gm.gender = 'F' THEN '여자' ELSE '' END AS gender FROM tb_dgnss_info a1 INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN tb_dgnss_answer c1 ON b1.id = c1.DGNSS_RESULT_ID LEFT JOIN tb_dgnss_lpa_result lpa ON c1.ANSWER_IDX = lpa.answer_idx INNER JOIN group_info gi ON gi.cla_id = #{claId} INNER JOIN group_member gm ON gi.group_id = gm.group_id AND b1.stdt_id = gm.stdt_id WHERE a1.cla_id <> #{claId} AND a1.paper_idx = #{paperIdx} AND a1.ord_no = #{ordNo} AND a1.dgnss_at = 'N' AND b1.subm_at = 'Y'
AND b1.stdt_id IN
#{stdtId}
ORDER BY gm.member_no

