wer_report b1_9 WHERE b1_9.ANSWER_IDX = c1.ANSWER_IDX AND b1_9.SECTION_ID = '20-22-03-02-03-0') AS styAtti , (SELECT IF(ROUND(b1_10.T_SCORE) < 0, 0, ROUND(b1_10.T_SCORE)) FROM tb_dgnss_answer_report b1_10 WHERE b1_10.ANSWER_IDX = c1.ANSWER_IDX AND b1_10.SECTION_ID = '20-22-03-02-04-0') AS note , (SELECT IF(ROUND(b1_11.T_SCORE) < 0, 0, ROUND(b1_11.T_SCORE)) FROM tb_dgnss_answer_report b1_11 WHERE b1_11.ANSWER_IDX = c1.ANSWER_IDX AND b1_11.SECTION_ID = '20-22-03-02-05-0') AS test , CASE WHEN gm.gender = 'M' THEN '남자' WHEN gm.gender = 'F' THEN '여자' ELSE '' END AS gender FROM tb_dgnss_info a1 INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN tb_dgnss_answer c1 ON b1.id = c1.DGNSS_RESULT_ID LEFT JOIN tb_dgnss_lpa_result lpa ON c1.ANSWER_IDX = lpa.answer_idx INNER JOIN group_info gi ON gi.cla_id = #{claId} INNER JOIN group_member gm ON gi.group_id = gm.group_id AND b1.stdt_id = gm.stdt_id WHERE a1.cla_id <> #{claId} AND a1.paper_idx = #{paperIdx} AND a1.ord_no = #{ordNo} AND a1.dgnss_at = 'N' AND b1.subm_at = 'Y'
