/* DgnssMapper.selectStInfo */ SELECT a1.stdt_id AS stdtId , gm.nickname AS nickname , gm.member_no AS memberNo , DATE_FORMAT(a1.subm_dt,'%Y-%m-%d %H:%i:%s') AS eakStDt , b1.DGNSS_ORD AS ordNo , a1_1.paper_idx AS paperIdx , a1_1.cla_id AS claId , CASE WHEN gm.gender = 'M' THEN '남자' WHEN gm.gender = 'F' THEN '여자' ELSE '' END AS gender , CASE WHEN gi.school_level = 'elementary' THEN '초등' WHEN gi.school_level = 'middle' THEN '중등' WHEN gi.school_level = 'high' THEN '고등' ELSE '' END AS grade , gi.group_nm AS classCd , gi.group_nm AS groupNm , a1.id AS dgnssResultId FROM tb_dgnss_info a1_1 INNER JOIN tb_dgnss_result_info a1 ON a1_1.id = a1.dgnss_id INNER JOIN tb_dgnss_answer b1 ON a1.id = b1.DGNSS_RESULT_ID INNER JOIN group_info gi ON a1_1.cla_id = gi.cla_id LEFT JOIN group_member gm ON gi.group_id = gm.group_id AND a1.stdt_id = gm.stdt_id WHERE 1=1
AND a1.id = #{dgnssResultId}
AND a1.stdt_id = #{stdtId} AND a1_1.paper_idx = #{paperIdx} AND a1_1.ord_no = #{ordNo}
AND a1_1.cla_id = #{claId}
ORDER BY a1.subm_dt DESC LIMIT 1

/* DgnssMapper.selectFirstDgnssResultId */
SELECT b1.id
FROM tb_dgnss_info a1
	INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id
WHERE a1.ord_no = 1
	AND b1.stdt_id = #{stdtId}
	AND a1.paper_idx = #{paperIdx}

/* DgnssMapper.selectStAnalysis */
SELECT CONCAT('{', GROUP_CONCAT(
	CONCAT('"', b1.SECTION_ID, '"', ' : "', IF(b1.T_SCORE < 0, 0, b1.T_SCORE), '_', b1.P_RANK, '"')), '}')
FROM tb_dgnss_info tdi
	INNER JOIN tb_dgnss_result_info tdri ON tdi.id = tdri.dgnss_id
	INNER JOIN tb_dgnss_answer a1 ON tdri.id = a1.DGNSS_RESULT_ID
	INNER JOIN tb_dgnss_answer_report b1 ON a1.ANSWER_IDX = b1.ANSWER_IDX
WHERE tdi.paper_idx = #{paperIdx}
	AND tdi.ord_no = #{ordNo}
	AND tdri.stdt_id = #{stdtId}

mapper.update:
/* DgnssMapper.saveDgnssTextSave */
UPDATE tb_dgnss_info
SET dgnss_text = #{dgnssText}
WHERE id = #{dgnssId}

mapper.select:
/* DgnssMapper.selectTcTrustInfoList */ WITH base AS ( SELECT gm.member_no AS num , b1.stdt_id AS stdtId , c1.COCH_DGNSS_QESITM01_SCORE AS q01 , c1.REPEATED_RESPONSE_YN AS repYn , c1.COCH_DGNSS_QESITM02_SCORE AS q02 FROM tb_dgnss_info a1 INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN tb_dgnss_answer c1 ON b1.id = c1.DGNSS_RESULT_ID INNER JOIN group_info gi ON a1.cla_id = gi.cla_id INNER JOIN group_member gm ON gi.group_id = gm.group_id AND b1.stdt_id = gm.stdt_id WHERE a1.id = #{dgnssId} AND a1.dgnss_at = 'N' AND b1.subm_at = 'Y' ) SELECT 'reaction' AS item, num, stdtId FROM base WHERE q01 > 65
UNION ALL SELECT 'repeatResponse' AS item, num, stdtId FROM base WHERE repYn = 'Y'
UNION ALL SELECT 'desirable' AS item, num, stdtId FROM base WHERE q02 > CASE WHEN #{paperIdx} = '1' THEN 65 ELSE 70 END ORDER BY item, num

/* DgnssMapper.selectDgnssIdxList */
SELECT id
FROM tb_dgnss_info
WHERE cla_id = #{claId}
	AND paper_idx = #{paperIdx}
	AND dgnss_at = 'N'
ORDER BY ord_no

/* DgnssMapper.selectClassTotalReport */ SELECT a1.id , a1.ord_no , b1.stdt_id AS stdtId , MAX(lpa.class_id) AS lpaClassId , MAX(lpa.type_name) AS lpaTypeName , MAX(lpa.confidence) AS lpaConfidence , MAX(lpa.status) AS lpaStatus , MAX(lpa.probabilities_json) AS lpaProbabilitiesJson , CONCAT('{', GROUP_CONCAT( CONCAT('"', d1.SECTION_ID, '"', ' : ', d1.T_SCORE)), '}') AS json FROM tb_dgnss_info a1 INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN tb_dgnss_answer c1 ON b1.id = c1.DGNSS_RESULT_ID LEFT JOIN tb_dgnss_lpa_result lpa ON c1.ANSWER_IDX = lpa.answer_idx INNER JOIN tb_dgnss_answer_report d1 ON c1.ANSWER_IDX = d1.ANSWER_IDX INNER JOIN group_info gi ON a1.cla_id = gi.cla_id INNER JOIN group_member gm ON gi.group_id = gm.group_id AND b1.stdt_id = gm.stdt_id WHERE a1.id = #{dgnssId} AND a1.dgnss_at = 'N' AND b1.subm_at = 'Y'
AND c1.COCH_DGNSS_QESITM01_MARK <> '주의' AND c1.COCH_DGNSS_QESITM02_MARK <> '주의' AND c1.REPEATED_RESPONSE_YN <> 'Y'
AND IFNULL(c1.NO_ANS_CNT, 0) < 10 GROUP BY a1.`id`, b1.stdt_id

/* DgnssMapper.selectOrdNoByDgnssId */
SELECT ord_no
FROM tb_dgnss_info
WHERE id = #{dgnssId}
LIMIT 1

/* DgnssMapper.selectClassStudentsWithoutResultInClassForOrd */
SELECT gm.stdt_id
FROM group_info gi
	INNER JOIN group_member gm ON gi.group_id = gm.group_id
WHERE gi.cla_id = #{claId}
  AND NOT EXISTS (
  	SELECT 1
  	FROM tb_dgnss_info tdi
  		INNER JOIN tb_dgnss_result_info tdri ON tdi.id = tdri.dgnss_id
  	WHERE tdi.cla_id = #{claId}
  	  AND tdi.paper_idx = #{paperIdx}
  	  AND tdi.ord_no = #{ordNo}
  	  AND tdri.stdt_id = gm.stdt_id
  )
ORDER BY gm.member_no

/* DgnssMapper.selectClassTotalReportFromOtherClasses */ SELECT a1.id , a1.ord_no , b1.stdt_id AS stdtId , MAX(lpa.class_id) AS lpaClassId , MAX(lpa.type_name) AS lpaTypeName , MAX(lpa.confidence) AS lpaConfidence , MAX(lpa.status) AS lpaStatus , MAX(lpa.probabilities_json) AS lpaProbabilitiesJson , CONCAT('{', GROUP_CONCAT(CONCAT('"', d1.SECTION_ID, '"', ' : ', d1.T_SCORE)), '}') AS json FROM tb_dgnss_info a1 INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN tb_dgnss_answer c1 ON b1.id = c1.DGNSS_RESULT_ID LEFT JOIN tb_dgnss_lpa_result lpa ON c1.ANSWER_IDX = lpa.answer_idx INNER JOIN tb_dgnss_answer_report d1 ON c1.ANSWER_IDX = d1.ANSWER_IDX WHERE a1.cla_id <> #{claId} AND a1.paper_idx = #{paperIdx} AND a1.ord_no = #{ordNo} AND a1.dgnss_at = 'N' AND b1.subm_at = 'Y' AND b1.stdt_id IN
#{stdtId}
AND c1.COCH_DGNSS_QESITM01_MARK <> '주의' AND c1.COCH_DGNSS_QESITM02_MARK <> '주의' AND c1.REPEATED_RESPONSE_YN <> 'Y'
AND IFNULL(c1.NO_ANS_CNT, 0) < 10 GROUP BY a1.id, b1.stdt_id

/* DgnssMapper.selectClaIdByDgnssId */
SELECT cla_id
FROM tb_dgnss_info
WHERE id = #{dgnssId}
LIMIT 1

/* DgnssMapper.selectClassStudentsSubmStatusFromOtherClasses */
SELECT b1.stdt_id AS stdtId
	, MAX(b1.subm_at) AS submAt
FROM tb_dgnss_info a1
	INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id
WHERE a1.cla_id <> #{claId}
	AND a1.paper_idx = #{paperIdx}
	AND a1.ord_no = #{ordNo}
	AND a1.dgnss_at = 'N'
	AND b1.stdt_id IN

		#{stdtId}

GROUP BY b1.stdt_id

/* DgnssMapper.selectClassLernReport */ SELECT a1.id , a1.ord_no , d1.SECTION_ID , d1.`DEPTH` , e1.SECTION_NM , IF(ROUND(avg(d1.T_SCORE)) < 0, 0, ROUND(avg(d1.T_SCORE))) AS tScore FROM tb_dgnss_info a1 INNER JOIN tb_dgnss_result_info b1 ON a1.id = b1.dgnss_id INNER JOIN tb_dgnss_answer c1 ON b1.id = c1.DGNSS_RESULT_ID INNER JOIN tb_dgnss_answer_report d1 ON c1.ANSWER_IDX = d1.ANSWER_IDX INNER JOIN tb_dgnss_section e1 ON d1.SECTION_ID = e1.SECTION_ID WHERE a1.cla_id = #{claId} AND a1.paper_idx = '1' AND a1.dgnss_at = 'N' AND b1.subm_at = 'Y' AND a1.ord_no = #{ordNo}
AND c1.COCH_DGNSS_QESITM01_MARK <> '주의' AND c1.COCH_DGNSS_QESITM02_MARK <> '주의' AND c1.REPEATED_RESPONSE_YN <> 'Y'
GROUP BY a1.id, d1.SECTION_ID

