mapper.select:
/* DgnssMapper.selectTcClassMetaStats */ SELECT gi.cla_id AS claId , IFNULL(gi.group_nm, '-') AS groupNm , COUNT(DISTINCT gm.stdt_id) AS totalStudentCount , COUNT(DISTINCT CASE WHEN tdri.subm_at = 'Y' THEN tdri.stdt_id END) AS submittedStudentCount , COUNT( DISTINCT CASE WHEN tdri.subm_at = 'Y' AND ( da.COCH_DGNSS_QESITM01_MARK = '주의' OR da.COCH_DGNSS_QESITM02_MARK = '주의' OR da.REPEATED_RESPONSE_YN = 'Y' ) THEN tdri.stdt_id END ) AS reliabilityAlertCount FROM group_info gi INNER JOIN user u ON gi.host_user_no = u.user_no INNER JOIN group_member gm ON gi.group_id = gm.group_id LEFT JOIN tb_dgnss_info tdi ON tdi.cla_id = gi.cla_id AND tdi.paper_idx = #{paperIdx} AND tdi.ord_no IN (1, 2) LEFT JOIN tb_dgnss_result_info tdri ON tdri.dgnss_id = tdi.id AND tdri.stdt_id = gm.stdt_id LEFT JOIN tb_dgnss_answer da ON da.DGNSS_RESULT_ID = tdri.id WHERE u.tc_id = #{tcId}
AND gi.cla_id = #{claId}
GROUP BY gi.cla_id, gi.group_nm ORDER BY gi.group_nm

/* DgnssMapper.selectTcClassFactorAverages */ SELECT gi.cla_id AS claId , dar.DEPTH AS depth , dar.SECTION_ID AS sectionId , ROUND(AVG(IF(dar.T_SCORE < 0, 0, dar.T_SCORE)), 1) AS avgTScore FROM group_info gi INNER JOIN user u ON gi.host_user_no = u.user_no INNER JOIN group_member gm ON gi.group_id = gm.group_id INNER JOIN tb_dgnss_info tdi ON tdi.cla_id = gi.cla_id AND tdi.paper_idx = #{paperIdx} AND tdi.ord_no IN (1, 2) INNER JOIN tb_dgnss_result_info tdri ON tdri.dgnss_id = tdi.id AND tdri.stdt_id = gm.stdt_id AND tdri.subm_at = 'Y' INNER JOIN tb_dgnss_answer da ON da.DGNSS_RESULT_ID = tdri.id INNER JOIN tb_dgnss_answer_report dar ON dar.ANSWER_IDX = da.ANSWER_IDX WHERE u.tc_id = #{tcId}
AND gi.cla_id = #{claId}
GROUP BY gi.cla_id, dar.DEPTH, dar.SECTION_ID

/* DgnssMapper.countDgnssResultByDgnssIdAndStdtId */
SELECT COUNT(*)
FROM tb_dgnss_result_info
WHERE dgnss_id = #{dgnssId}
  AND stdt_id = #{stdtId}

/* DgnssMapper.selectValidOmrIdxSetByDgnssId */
SELECT tdo.OMR_IDX
FROM tb_dgnss_result_info tdri
	INNER JOIN tb_dgnss_omr tdo ON tdri.omr_id = tdo.OMR_IDX
WHERE tdri.dgnss_id = #{dgnssId}

/* DgnssMapper.existsOmrIdx */
SELECT COUNT(*)
FROM tb_dgnss_omr
WHERE OMR_IDX = #{omrIdx}
